const event = (id, fields = {}) => ({
  recordType: 'event',
  id,
  title: 'Encuentro de AWS',
  description: 'Un encuentro para la comunidad AWS.',
  startsAt: '2100-01-01T10:00:00Z',
  endsAt: '2100-01-01T12:00:00Z',
  timeZone: 'UTC',
  organizer: 'Comunidad AWS',
  mode: 'in-person',
  place: 'Auditorio central',
  country: 'AR',
  registrationUrl: `https://example.test/eventos/${id}`,
  published: true,
  directoryControl: 'editorial',
  ...fields,
});

const community = (id, city) => ({
  id,
  title: `Sede ${city}`,
  url: `https://example.test/comunidades/${id}`,
  description: `Comunidad de ${city}.`,
  category: 'Comunidad',
  order: 1,
  featured: false,
  kind: 'community',
  format: 'User Group',
  topics: [],
  country: 'AR',
  city,
  published: true,
});

const creator = (id, displayName, slug, {
  hidden = false,
  links = [],
  series = [],
  bio,
} = {}) => {
  const placements = Object.fromEntries(links.map(({ resourceId, selectedForDirectory = true }) => [
    `${id}-${resourceId}`,
    { resourceId, selectedForDirectory },
  ]));
  const placementIdByResource = new Map(links.map(({ resourceId }) => [resourceId, `${id}-${resourceId}`]));
  return {
    id,
    schemaVersion: 2,
    version: 1,
    displayName,
    slug,
    published: true,
    hidden,
    ...(bio === undefined ? {} : { bio }),
    placements,
    order: { featured: [], ordinary: Object.keys(placements) },
    series: Object.fromEntries(series.map(({ id: seriesId, name, slug: seriesSlug, resourceIds, description }) => [
      seriesId,
      {
        name,
        slug: seriesSlug,
        ...(description === undefined ? {} : { description }),
        chapters: resourceIds.map((resourceId) => placementIdByResource.get(resourceId)),
      },
    ])),
  };
};

